import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"О Memoh","description":"","frontmatter":{},"headers":[],"relativePath":"ru/about.md","filePath":"ru/about.md","lastUpdated":1792323081000}'),l={name:"ru/about.md"};function h(s,e,i,n,d,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="о-memoh" tabindex="-1">О Memoh <a class="header-anchor" href="#о-memoh" aria-label="Permalink to &quot;О Memoh&quot;">​</a></h1><p>Memoh v0.13 — мультиагентная платформа с открытым исходным кодом. Она позволяет запускать на одной машине несколько ИИ-агентов, и каждый агент получает собственное рабочее пространство, браузер, сеть, инструменты и долговременную память.</p><p>Агенты могут общаться через Telegram, Discord, Slack, Feishu, WeChat, DingTalk и другие каналы — а также напрямую в приложении Memoh. Они умеют запоминать контекст, управлять браузером или рабочим столом, вызывать инструменты MCP, устанавливать навыки и коннекторы, выполнять задачи по расписанию и соблюдать правила доступа, заданные для каждого Bot.</p><p>Предпочитаете управляемый вариант вместо собственного развёртывания? <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> — тот же продукт в виде облачного сервиса.</p><h2 id="форматы-поставки" tabindex="-1">Форматы поставки <a class="header-anchor" href="#форматы-поставки" aria-label="Permalink to &quot;Форматы поставки&quot;">​</a></h2><h3 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h3><p>Desktop — нативный клиент для Memoh Cloud или самостоятельно развёрнутого сервера. Он оборачивает тот же клиентский интерфейс в нативное окно с системным треем и горячими клавишами и может зарегистрировать компьютер, на котором работает, как Computer, доступный Bot. Локальный сервер он не запускает.</p><h3 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h3><p>Server Deploy — для постоянной совместной работы. Используйте его, когда Memoh должен обслуживать нескольких пользователей, держать каналы онлайн, пока ваш компьютер не в сети, или работать как самостоятельно развёрнутый сервис. Стек Docker Compose включает бэкенд, веб-клиент, базу данных, сервисы памяти и рантайм рабочих пространств.</p><h2 id="главное-в-v0-13" tabindex="-1">Главное в v0.13 <a class="header-anchor" href="#главное-в-v0-13" aria-label="Permalink to &quot;Главное в v0.13&quot;">​</a></h2><h3 id="рабочие-пространства-агентов" tabindex="-1">Рабочие пространства агентов <a class="header-anchor" href="#рабочие-пространства-агентов" aria-label="Permalink to &quot;Рабочие пространства агентов&quot;">​</a></h3><p>Каждый Bot может использовать изолированное контейнерное рабочее пространство с файлами, командами, хостингом MCP, доступом к сети, браузером с графическим интерфейсом (headed) и графическим рабочим столом. Локальные и настольные конфигурации могут также использовать доверенные локальные рабочие пространства, когда доступ на уровне хоста даётся осознанно.</p><h3 id="клиент" tabindex="-1">Клиент <a class="header-anchor" href="#клиент" aria-label="Permalink to &quot;Клиент&quot;">​</a></h3><p>Клиент теперь покрывает больше повседневных задач: настройку Bot, сессии, провайдеров, каналы, файлы рабочего пространства, панели терминала и рабочего стола, Supermarket, Hooks, задачи по расписанию, контроль доступа и пользовательские настройки. В v0.13 также появилась поддержка английского, упрощённого китайского и японского языков интерфейса.</p><h3 id="hooks-расписания-и-автоматизация" tabindex="-1">Hooks, расписания и автоматизация <a class="header-anchor" href="#hooks-расписания-и-автоматизация" aria-label="Permalink to &quot;Hooks, расписания и автоматизация&quot;">​</a></h3><p>Hooks позволяют Bot выполнять небольшие правила автоматизации вокруг поддерживаемых событий, а Schedule поддерживает регулярную работу без активного чата. Навыки и коннекторы из Supermarket расширяют возможности Bot без написания кода.</p><h3 id="контроль-доступа" tabindex="-1">Контроль доступа <a class="header-anchor" href="#контроль-доступа" aria-label="Permalink to &quot;Контроль доступа&quot;">​</a></h3><p>Контроль доступа разделён на права чата на стороне канала и права пользователей на стороне рабочего пространства. Владельцы Bot могут разрешать или блокировать участников канала, выдавать зарегистрированным пользователям роли рабочего пространства, а для случаев, где нужно более точное сопоставление, — использовать продвинутые правила ACL.</p><h2 id="с-чего-начать" tabindex="-1">С чего начать <a class="header-anchor" href="#с-чего-начать" aria-label="Permalink to &quot;С чего начать&quot;">​</a></h2><ul><li><strong><a href="./guides/working-with-bots.html">Настройка Bot</a></strong> - создайте и настройте Bot.</li><li><strong><a href="./integrations/providers/llm.html">Провайдеры и модели</a></strong> - настройте доступ к моделям.</li><li><strong><a href="./integrations/channels/">Каналы</a></strong> - выберите, где Bot будут доступны.</li><li><strong><a href="./guides/skills.html">Навыки</a></strong> и <strong><a href="./guides/supermarket.html">Supermarket</a></strong> - установите переиспользуемые возможности.</li><li><strong><a href="./guides/schedule.html">Задачи по расписанию</a></strong> и <strong><a href="./guides/access.html">Контроль доступа</a></strong> - управляйте регулярной работой и правами.</li><li><strong><a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Центр помощи</a></strong> - тарифы, оплата и вопросы по учётной записи, а также прямая связь с командой.</li></ul>',20)])])}const c=a(l,[["render",h]]);export{u as __pageData,c as default};
